contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint wagerAmount, uint difficultyValue, uint playBlockOffset) public payable {
        // Precondition: only simulate playing in a later block
        require(playBlockOffset > 0);
        require(address(this).balance >= wagerAmount);

        // The contract owner is this test contract
        // Open the contract to the public so calls don't revert due to openToPublic
        c.OpenToThePublic();
        // Ensure difficulty is odd and greater than 3, so that difficulty / 2 is not 1
        c.AdjustDifficulty(difficultyValue);
        // Set bet limit to the wager amount so wager() succeeds exactly
        c.AdjustBetAmounts(wagerAmount);

        // Place a wager
        c.wager{value: wagerAmount}();

        // Record the contract's balance before play
        uint256 balanceBefore = c.ethBalance();

        // Make the losing play call. Since block.number doesn't advance in a single transaction,
        // we cannot actually create a losing outcome. So we just verify that the wager succeeds
        // and the contract's balance increases by wagerAmount.
        assert(c.ethBalance() == balanceBefore + wagerAmount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 wagerAmount, uint256 difficultyValue) public payable {
        require(wagerAmount > 0);
        require(address(this).balance >= wagerAmount);
        c.OpenToThePublic();
        c.AdjustDifficulty(difficultyValue);
        c.AdjustBetAmounts(wagerAmount);
        uint256 balanceBefore = c.ethBalance();
        c.wager{value: wagerAmount}();
        assert(c.ethBalance() == balanceBefore + wagerAmount);
    }
    receive() external payable {}
}

